/**
 * Validation Middleware — Request body/query/params validation using Joi.
 * Generated by BackendForge
 */

const Joi = require('joi');

/**
 * Create a validation middleware for the given schema.
 * @param {object} schema - { body: JoiSchema, query: JoiSchema, params: JoiSchema }
 */
const validate = (schema) => {
  return (req, res, next) => {
    const errors = [];

    ['body', 'query', 'params'].forEach((key) => {
      if (schema[key]) {
        const { error, value } = schema[key].validate(req[key], {
          abortEarly: false,
          stripUnknown: true,
        });
        if (error) {
          errors.push(...error.details.map(d => ({
            field: d.path.join('.'),
            message: d.message.replace(/"/g, ''),
            type: d.type,
            source: key,
          })));
        } else {
          req[key] = value; // Replace with sanitized value
        }
      }
    });

    if (errors.length > 0) {
      return res.status(400).json({
        success: false,
        message: 'Validation failed',
        code: 'VALIDATION_ERROR',
        details: errors,
      });
    }

    next();
  };
};

// ─── Common Validation Schemas ──────────────────────────────

const schemas = {
  // Auth
  register: {
    body: Joi.object({
      name: Joi.string().trim().min(1).max(100).required(),
      email: Joi.string().email().required(),
      phone: Joi.string().pattern(/^\+?[1-9]\d{6,14}$/).allow('', null),
      password: Joi.string().min(8).max(128).required()
        .pattern(/^(?=.*[a-z])(?=.*[A-Z])(?=.*\d)/)
        .message('Password must contain at least one uppercase letter, one lowercase letter, and one number'),
    }),
  },

  login: {
    body: Joi.object({
      email: Joi.string().email().required(),
      password: Joi.string().required(),
    }),
  },

  adminLogin: {
    body: Joi.object({
      email: Joi.string().email().required(),
      password: Joi.string().required(),
    }),
  },

  verifyOtp: {
    body: Joi.object({
      userId: Joi.string().required(),
      code: Joi.string().length(6).required(),
    }),
  },

  // Profile
  updateProfile: {
    body: Joi.object({
      name: Joi.string().trim().min(1).max(100),
      phone: Joi.string().pattern(/^\+?[1-9]\d{6,14}$/).allow('', null),
      avatar: Joi.string().uri().allow('', null),
    }),
  },

  // Product
  createProduct: {
    body: Joi.object({
      name: Joi.string().trim().min(1).max(200).required(),
      description: Joi.string().required(),
      shortDescription: Joi.string().max(300),
      price: Joi.number().positive().required(),
      compareAtPrice: Joi.number().positive().allow(null),
      costPrice: Joi.number().positive().allow(null),
      sku: Joi.string().max(100),
      stock: Joi.number().integer().min(0).required(),
      categoryId: Joi.string().allow(null),
      images: Joi.array().items(Joi.object({ url: Joi.string().uri(), alt: Joi.string(), isPrimary: Joi.boolean() })),
      tags: Joi.array().items(Joi.string()),
      isActive: Joi.boolean(),
      isFeatured: Joi.boolean(),
    }),
  },

  // Order
  createOrder: {
    body: Joi.object({
      shippingAddressId: Joi.string().required(),
      paymentMethod: Joi.string().valid('card', 'upi', 'netbanking', 'wallet', 'cod').required(),
      customerNotes: Joi.string().max(500).allow('', null),
      couponCode: Joi.string().allow('', null),
    }),
  },

  cancelOrder: {
    body: Joi.object({
      reason: Joi.string().max(500).required(),
    }),
  },

  updateShippingStatus: {
    body: Joi.object({
      shippingStatus: Joi.string().valid(
        'confirmed', 'processing', 'packed', 'shipped', 'in_transit', 'out_for_delivery', 'delivered', 'returned'
      ).required(),
      trackingNumber: Joi.string().allow('', null),
      carrier: Joi.string().allow('', null),
      estimatedDelivery: Joi.date().allow(null),
      adminNotes: Joi.string().max(500).allow('', null),
    }),
  },

  // Cart
  addToCart: {
    body: Joi.object({
      productId: Joi.string().required(),
      quantity: Joi.number().integer().min(1).default(1),
      variant: Joi.object().allow(null),
    }),
  },

  // Pagination query
  pagination: {
    query: Joi.object({
      page: Joi.number().integer().min(1).default(1),
      limit: Joi.number().integer().min(1).max(100).default(20),
      sort: Joi.string().default('createdAt'),
      order: Joi.string().valid('asc', 'desc', 'ASC', 'DESC').default('desc'),
      search: Joi.string().allow('', null),
    }),
  },

  // ID param
  idParam: {
    params: Joi.object({
      id: Joi.string().required(),
    }),
  },
};

module.exports = { validate, schemas };
